WITH with_gaps AS (SELECT *, CASE WHEN paid_at - LAG(paid_at) OVER (PARTITION BY order_id ORDER BY paid_at, id) > INTERVAL '60' DAY THEN 1 ELSE 0 END AS session_start_flag FROM payments), sessionized AS (SELECT *, SUM(session_start_flag) OVER (PARTITION BY order_id ORDER BY paid_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM with_gaps) SELECT CASE WHEN amount >= 1790 THEN 'LARGE' ELSE 'SMALL' END AS amount_tier, COUNT_IF(status = 'FAILED') AS failed_events, SUM(CASE WHEN method = 'paypal' THEN amount ELSE 0 END) AS paypal_amount, COUNT(CASE WHEN status = 'SUCCESS' THEN 1 END) AS success_count, APPROX_PERCENTILE(amount, 0.95) AS amount_p95, ROUND(SUM(amount) / NULLIF(COUNT(CASE WHEN status = 'REFUNDED' THEN 1 END), 0), 2) AS amount_per_refunded, COUNT(*) FILTER (WHERE status = 'REFUNDED') AS refunded_rows, GROUPING(CASE WHEN amount >= 1790 THEN 'LARGE' ELSE 'SMALL' END) AS grouping_id FROM sessionized GROUP BY ROLLUP (CASE WHEN amount >= 1790 THEN 'LARGE' ELSE 'SMALL' END) ORDER BY success_count DESC;
